import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int P = sc.nextInt();

        int[] f = new int[m + 1];
        int[] g = new int[m + 1];
        int[][] C = new int[m + 1][m + 1];

        f[0] = 1;
        for (int i = 0; i <= m; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = (C[i - 1][j] + C[i - 1][j - 1]) % P;
            }
        }

        // Helper method for updating values modulo P
        class Upd {
            void update(int[] x, int y) {
                x[0] += y;
                if (x[0] >= P) x[0] -= P;
            }
        }
        Upd updater = new Upd();

        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= i; j++) {
                int temp1 = (int)((long)f[j - 1] * f[i - j] % P * (i + 1) % P * C[i - 1][j - 1] % P);
                int temp2 = (int)(((long)f[j - 1] * g[i - j] + (long)f[i - j] * g[j - 1]) % P * (i + 1) % P * C[i - 1][j - 1] % P);
                int temp3 = (int)((long)(C[j][2] + C[i - j + 1][2]) * f[j - 1] % P * f[i - j] % P * C[i - 1][j - 1] % P);

                int[] f_i = {f[i]};
                int[] g_i = {g[i]};
                updater.update(f_i, temp1);
                updater.update(g_i, temp2);
                updater.update(g_i, temp3);
                f[i] = f_i[0];
                g[i] = g_i[0];
            }
        }

        int[][] p = new int[n + 1][m + 1];
        int[][] q = new int[n + 1][m + 1];

        p[0][0] = 1;

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= Math.min(i - 1, m); j++) {
                for (int k = 0; k <= j; k++) {
                    int temp1 = (int)((long)p[i - k - 1][j - k] * f[k] % P * C[j][k] % P);
                    int temp2 = (int)(((long)p[i - k - 1][j - k] * g[k] + (long)q[i - k - 1][j - k] * f[k]) % P * C[j][k] % P);

                    int[] pVal = {p[i][j]};
                    int[] qVal = {q[i][j]};
                    updater.update(pVal, temp1);
                    updater.update(qVal, temp2);
                    p[i][j] = pVal[0];
                    q[i][j] = qVal[0];
                }
            }
            if (i <= m) {
                p[i][i] = f[i];
                q[i][i] = g[i];
            }
        }

        System.out.println(q[n][m]);
        sc.close();
    }
}

